Import PMES.
Section FromIntOk.
Context {SCFG_P : ScfgP}.
Variable L : asan_layout.
Variable ar : asan_run.
Variable C : asan_statics_cells.
Variable HI : asan_iface.
Hypothesis HIok : PmHeapIfaceA.asan_iface_ok L ar C SCFG HI.
Hypothesis LAY : L5A.as0_layout L C.
Hypothesis SM3 : hl_stack_malloc L 3 = FIXB.PC_SM.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps (hl_segs L) (@mkst fx R (Z_to_bv 64 pc) M (seg_rom (hl_segs L))) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom (hl_segs L))) -> PMSA.fp_ok fx -> PMSA.fp_ok fx'.
Variable CL : Z.                        (* [comment removed for export] *)
Abbreviation IC := PMLA.C_xboth.
Abbreviation RSEGS := (hl_segs L).
Hypothesis PUSHB_OK : PMESA.str_push_back_x_specA L ar HI CL FIXB.PUSHB.            (* [comment removed for export] *)
Hypothesis SETSH : aset_shadow_spec L ar SCFG HI FIXB.PC_SETSH 245 256.           (* [comment removed for export] *)

Definition hid (P : Prop) : Prop := P.

(* [comment removed for export] *)
Definition cnt (i : nat) (E : env) (p : Z) : Prop :=
  match i with
  | 0%nat | 4%nat => p = 0
  | 1%nat => p = 0 /\ 1 <= CL5A.uv E FIXB.CE <= 19
  | 5%nat => p = 1 /\ 1 <= CL5A.uv E FIXB.CE <= 19
  | 2%nat | 3%nat => p = CL5A.uv E FIXB.TE - CL5A.uv E FIXB.KE /\ 1 <= CL5A.uv E FIXB.TE <= 20
  | 6%nat => p = CL5A.uv E FIXB.TE - CL5A.uv E FIXB.KE + 1 /\ 1 <= CL5A.uv E FIXB.TE <= 20
  | 7%nat => p = CL5A.uv E FIXB.TE /\ 1 <= CL5A.uv E FIXB.TE <= 20
  | _ => False
  end.

